import{_ as t,o as s,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"围棋战略基础","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/weiqi/weiqi-strategy-basics.md","filePath":"topics/weiqi/weiqi-strategy-basics.md"}'),d={name:"topics/weiqi/weiqi-strategy-basics.md"};function l(i,a,p,r,o,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="围棋战略基础" tabindex="-1">围棋战略基础 <a class="header-anchor" href="#围棋战略基础" aria-label="Permalink to &quot;围棋战略基础&quot;">​</a></h1><blockquote><p>来源：古力九段讲解视频，2026-06-16</p></blockquote><hr><h2 id="一、围棋核心本质" tabindex="-1">一、围棋核心本质 <a class="header-anchor" href="#一、围棋核心本质" aria-label="Permalink to &quot;一、围棋核心本质&quot;">​</a></h2><blockquote><p><strong>围棋的本质不是杀棋，是减少自己的断点。</strong></p></blockquote><ul><li>走棋的目标：<strong>让自己的棋更强、更安全</strong></li><li>杀对方的棋是结果，不是目的</li><li>死记棋谱没用，要理解&quot;为什么这么走&quot;</li></ul><hr><h2 id="二、核心概念-断点" tabindex="-1">二、核心概念：断点 <a class="header-anchor" href="#二、核心概念-断点" aria-label="Permalink to &quot;二、核心概念：断点&quot;">​</a></h2><h3 id="什么是断点" tabindex="-1">什么是断点 <a class="header-anchor" href="#什么是断点" aria-label="Permalink to &quot;什么是断点&quot;">​</a></h3><p>棋子和棋子之间的<strong>断口</strong>，就是潜在的弱点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常连接（无断点）：</span></span>
<span class="line"><span>○○○○○○○  ← 一条完整的线，稳固</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有断点：</span></span>
<span class="line"><span>○○○●○○○  ← 中间那个●就是断点，薄弱环节</span></span></code></pre></div><h3 id="断点的危害" tabindex="-1">断点的危害 <a class="header-anchor" href="#断点的危害" aria-label="Permalink to &quot;断点的危害&quot;">​</a></h3><table tabindex="0"><thead><tr><th>危害程度</th><th>说明</th></tr></thead><tbody><tr><td>轻度</td><td>被对方攻击，疲于逃跑</td></tr><tr><td>中度</td><td>被切断，损失实地</td></tr><tr><td>重度</td><td>整块棋被围，面临生死</td></tr></tbody></table><h3 id="围棋的胜负手往往在断点" tabindex="-1">围棋的胜负手往往在断点 <a class="header-anchor" href="#围棋的胜负手往往在断点" aria-label="Permalink to &quot;围棋的胜负手往往在断点&quot;">​</a></h3><ul><li><strong>自己的断点</strong>：先补好，不给对手可乘之机</li><li><strong>对手的断点</strong>：瞄准它，打入或攻击</li></ul><hr><h2 id="三、冲的用法-最关键" tabindex="-1">三、冲的用法（最关键） <a class="header-anchor" href="#三、冲的用法-最关键" aria-label="Permalink to &quot;三、冲的用法（最关键）&quot;">​</a></h2><h3 id="规则-能断才冲" tabindex="-1">规则：能断才冲 <a class="header-anchor" href="#规则-能断才冲" aria-label="Permalink to &quot;规则：能断才冲&quot;">​</a></h3><p><strong>&quot;冲&quot;是围棋术语，指用自己的棋子主动向外冲出一条路。</strong></p><p>核心原则：</p><table tabindex="0"><thead><tr><th>情况</th><th>判断</th><th>行动</th></tr></thead><tbody><tr><td>冲出去能断对手</td><td>✅ 能断</td><td><strong>冲</strong></td></tr><tr><td>冲出去断不了</td><td>❌ 不能断</td><td><strong>不冲</strong>，否则帮对方走棋</td></tr><tr><td>冲了反而留新断点</td><td>❌ 有风险</td><td>不冲</td></tr></tbody></table><h3 id="具体案例" tabindex="-1">具体案例 <a class="header-anchor" href="#具体案例" aria-label="Permalink to &quot;具体案例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>局面：黑棋被围，想逃</span></span>
<span class="line"><span></span></span>
<span class="line"><span>❌ 错误思路：</span></span>
<span class="line"><span>  看到缝隙就往里冲，结果冲完反而多了一个断点</span></span>
<span class="line"><span>  → 冲一次，多一个弱点，亏了</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 正确思路：</span></span>
<span class="line"><span>  先算清楚：冲出去能断掉对方的什么？</span></span>
<span class="line"><span>  如果什么都断不了，就先补自己的棋</span></span>
<span class="line"><span>  → 老老实实走好，等对手犯错</span></span></code></pre></div><hr><h2 id="四、走法选择-四象限法" tabindex="-1">四、走法选择：四象限法 <a class="header-anchor" href="#四、走法选择-四象限法" aria-label="Permalink to &quot;四、走法选择：四象限法&quot;">​</a></h2><h3 id="好走法-vs-坏走法" tabindex="-1">好走法 vs 坏走法 <a class="header-anchor" href="#好走法-vs-坏走法" aria-label="Permalink to &quot;好走法 vs 坏走法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>走法</th><th>特点</th><th>效果</th></tr></thead><tbody><tr><td><strong>飞</strong></td><td>像鸟一样飞，斜着走</td><td>✅ 减少断点，稳健</td></tr><tr><td><strong>退</strong></td><td>往后走一步</td><td>✅ 减少断点，稳健</td></tr><tr><td><strong>跳</strong></td><td>跳一格</td><td>⚠️ 留断点，进攻性强</td></tr><tr><td><strong>虎</strong></td><td>形成虎口（护断点）</td><td>⚠️ 有一定断点风险</td></tr></tbody></table><h3 id="判断框架" tabindex="-1">判断框架 <a class="header-anchor" href="#判断框架" aria-label="Permalink to &quot;判断框架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>走这步棋之前，问自己：</span></span>
<span class="line"><span>1. 走完之后，我的断点变多了还是变少了？</span></span>
<span class="line"><span>2. 走完之后，对手的断点变多了还是变少了？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者都变少 → ✅ 必走</span></span>
<span class="line"><span>只有自己变少 → ✅ 可以走</span></span>
<span class="line"><span>自己变多 → ❌ 不走</span></span></code></pre></div><hr><h2 id="五、实战原则-5条" tabindex="-1">五、实战原则（5条） <a class="header-anchor" href="#五、实战原则-5条" aria-label="Permalink to &quot;五、实战原则（5条）&quot;">​</a></h2><h3 id="_1-先补自己的断点" tabindex="-1">1. 先补自己的断点 <a class="header-anchor" href="#_1-先补自己的断点" aria-label="Permalink to &quot;1. 先补自己的断点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误：一直想杀对方的棋，自己漏洞百出</span></span>
<span class="line"><span>正确：先把断点补好，再找机会进攻</span></span></code></pre></div><h3 id="_2-算清楚再动手" tabindex="-1">2. 算清楚再动手 <a class="header-anchor" href="#_2-算清楚再动手" aria-label="Permalink to &quot;2. 算清楚再动手&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误：感觉这里能杀，冲进去再说</span></span>
<span class="line"><span>正确：算清楚——能断吗？断完能活吗？断完对手怎么应？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>围棋不是比谁敢冲，是比谁算得清</span></span></code></pre></div><h3 id="_3-能断才冲-不能断老实待着" tabindex="-1">3. 能断才冲，不能断老实待着 <a class="header-anchor" href="#_3-能断才冲-不能断老实待着" aria-label="Permalink to &quot;3. 能断才冲，不能断老实待着&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>核心口诀：</span></span>
<span class="line"><span>&quot;能断则断，不能断则守&quot;</span></span>
<span class="line"><span>&quot;冲一次，多一个弱点，亏了&quot;</span></span></code></pre></div><h3 id="_4-走好自己的棋-等对手犯错" tabindex="-1">4. 走好自己的棋，等对手犯错 <a class="header-anchor" href="#_4-走好自己的棋-等对手犯错" aria-label="Permalink to &quot;4. 走好自己的棋，等对手犯错&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>围棋是比谁少犯错，不是比谁更激进</span></span>
<span class="line"><span>高手赢棋靠：自己不犯错 + 等对手犯错</span></span></code></pre></div><h3 id="_5-整体观念-弃子取势" tabindex="-1">5. 整体观念：弃子取势 <a class="header-anchor" href="#_5-整体观念-弃子取势" aria-label="Permalink to &quot;5. 整体观念：弃子取势&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>局部亏一点，整体领先 = 赢</span></span>
<span class="line"><span>死一块棋不影响全局 = 可以舍</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要为了救一块棋，把整盘都拖下水</span></span></code></pre></div><hr><h2 id="六、与投资的类比" tabindex="-1">六、与投资的类比 <a class="header-anchor" href="#六、与投资的类比" aria-label="Permalink to &quot;六、与投资的类比&quot;">​</a></h2><blockquote><p>围棋战略和投资决策高度相通</p></blockquote><table tabindex="0"><thead><tr><th>围棋原则</th><th>投资映射</th></tr></thead><tbody><tr><td>能断才冲</td><td>能算清楚赔率才下单</td></tr><tr><td>先堵自己的断点</td><td>先设止损线</td></tr><tr><td>老老实实走好</td><td>在能力圈内投资</td></tr><tr><td>等对手犯错</td><td>等市场犯错（恐慌时买）</td></tr><tr><td>局部亏整体赢</td><td>控制单笔亏损，追求总回报</td></tr><tr><td>不为救一块棋拖全局</td><td>不为救一只烂股卖好股</td></tr><tr><td>算清楚再动手</td><td>搞不懂就不碰</td></tr></tbody></table><p><strong>核心纪律</strong>：</p><ul><li>投资不是比谁胆子大，是比谁不犯大错</li><li>少亏 = 少断点，不亏 = 不输</li><li>等机会出现再出手，不是每天都要交易</li></ul><hr><h2 id="七、学习建议" tabindex="-1">七、学习建议 <a class="header-anchor" href="#七、学习建议" aria-label="Permalink to &quot;七、学习建议&quot;">​</a></h2><h3 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>工具</th></tr></thead><tbody><tr><td>看规则</td><td>围棋基本规则、棋子、气、禁入点</td><td>围棋APP入门教程</td></tr><tr><td>死活</td><td>做死活题，理解棋的死活</td><td>围棋101题、野狐围棋</td></tr><tr><td>手筋</td><td>常用的吃子手段</td><td>弈城围棋</td></tr><tr><td>布局</td><td>常见布局、定式</td><td>围棋书籍</td></tr><tr><td>中盘</td><td>攻防、断点、厚薄</td><td>古力/柯洁解说视频</td></tr></tbody></table><h3 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>古力九段视频</td><td>B站/抖音</td><td>实战讲解，战略思维</td></tr><tr><td>柯洁解说</td><td>B站</td><td>高手视角</td></tr><tr><td>野狐围棋</td><td>APP</td><td>实战对弈</td></tr><tr><td>腾讯围棋</td><td>APP</td><td>题库练习</td></tr><tr><td>《围棋入门》</td><td>书籍</td><td>系统学习</td></tr></tbody></table><h3 id="每天练习" tabindex="-1">每天练习 <a class="header-anchor" href="#每天练习" aria-label="Permalink to &quot;每天练习&quot;">​</a></h3><ul><li>死活题：每天10道（10-15分钟）</li><li>对弈：每天1-2局（不在乎输赢，在乎复盘）</li><li>复盘：每局棋想一想——哪里有断点？我有没有犯？</li></ul><hr><h2 id="九、围棋规则-双活-seki" tabindex="-1">九、围棋规则：双活（Seki） <a class="header-anchor" href="#九、围棋规则-双活-seki" aria-label="Permalink to &quot;九、围棋规则：双活（Seki）&quot;">​</a></h2><h3 id="什么是双活" tabindex="-1">什么是双活 <a class="header-anchor" href="#什么是双活" aria-label="Permalink to &quot;什么是双活&quot;">​</a></h3><p>双方棋子互相卡住，<strong>谁都吃不掉对方，但谁都不会死</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│ ● ● ● ○ ○ ○ │  ← 双方棋子都算&quot;活子&quot;</span></span>
<span class="line"><span>│ ● ✕ ✕ ✕ ○ │  ← ✕ = 公气（双方共用）</span></span>
<span class="line"><span>│ ● ● ● ○ ○ ○ │</span></span>
<span class="line"><span>└─────────────┘</span></span></code></pre></div><h3 id="为什么会出现双活" tabindex="-1">为什么会出现双活？ <a class="header-anchor" href="#为什么会出现双活" aria-label="Permalink to &quot;为什么会出现双活？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前提：双方都&quot;没眼&quot;或&quot;只有一只眼&quot;，互相卡住</span></span>
<span class="line"><span></span></span>
<span class="line"><span>黑棋吃白棋 → 需要先填公气 → 填完公气自己只剩一口气 → 被白棋反吃</span></span>
<span class="line"><span>白棋吃黑棋 → 同理 → 被黑棋反吃</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 双方都不敢动手 → 双活</span></span></code></pre></div><h3 id="三种双活类型" tabindex="-1">三种双活类型 <a class="header-anchor" href="#三种双活类型" aria-label="Permalink to &quot;三种双活类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特征</th><th>公气</th></tr></thead><tbody><tr><td><strong>无眼双活</strong></td><td>双方都没眼，共享公气</td><td>≥ 2 口</td></tr><tr><td><strong>单眼双活</strong></td><td>一方有眼一方无眼</td><td>≥ 1 口</td></tr><tr><td><strong>双眼双活</strong></td><td>双方各有一只眼</td><td>≥ 1 口</td></tr></tbody></table><h3 id="中国规则-数子法-vs-日韩规则-数目法" tabindex="-1">中国规则（数子法）vs 日韩规则（数目法） <a class="header-anchor" href="#中国规则-数子法-vs-日韩规则-数目法" aria-label="Permalink to &quot;中国规则（数子法）vs 日韩规则（数目法）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>双活区域的棋子</th><th>公气</th><th>目数</th></tr></thead><tbody><tr><td>🇨🇳 <strong>中国规则</strong></td><td>✅ 双方棋子都算活子</td><td>❌ 不算给任何一方</td><td>子空皆地</td></tr><tr><td>🇯🇵 <strong>日韩规则</strong></td><td>✅ 棋子活着</td><td>❌ 不算目</td><td>❌ 双活区域不产生目数</td></tr></tbody></table><h3 id="实战判断" tabindex="-1">实战判断 <a class="header-anchor" href="#实战判断" aria-label="Permalink to &quot;实战判断&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>判断双活的前提：</span></span>
<span class="line"><span>1. 双方的眼位都不够（都做不出两只真眼）</span></span>
<span class="line"><span>2. 双方都不敢先动手（先动手=自杀）</span></span>
<span class="line"><span>3. 公气 ≥ 2（无眼双活）或 ≥ 1（有眼双活）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>❌ 不是双活：一方有两只真眼 → 对方死棋</span></span>
<span class="line"><span>❌ 不是双活：公气只有 1 口且双方无眼 → 先动手方吃掉对方</span></span></code></pre></div><hr><h2 id="十、围棋ai辅助学习" tabindex="-1">十、围棋AI辅助学习 <a class="header-anchor" href="#十、围棋ai辅助学习" aria-label="Permalink to &quot;十、围棋AI辅助学习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>AI工具</th><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>Katago</td><td>AI复盘</td><td>开源，免费，分析每步胜率</td></tr><tr><td>Leela Zero</td><td>围棋AI</td><td>了解AI的最优选点</td></tr><tr><td>星阵围棋</td><td>AI分析</td><td>中文界面，适合业余棋手</td></tr><tr><td>野狐AI</td><td>对弈辅助</td><td>边下边看胜率曲线</td></tr></tbody></table><blockquote><p><strong>提示</strong>：AI能告诉你最优解，但更重要的是理解&quot;为什么&quot;最优解。 记住：围棋是比谁少犯错，不是比谁更像AI。</p></blockquote>`,72)])])}const u=t(d,[["render",l]]);export{b as __pageData,u as default};
